package com.sakan.iptv;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class PlayerFeaturesTest {
 @Test public void guideDecodesTitlesOrdersAndFindsCurrent()throws Exception{long now=1700000000;JSONArray rows=new JSONArray().put(new JSONObject().put("id","next").put("title","TmV4dA==").put("start_timestamp",now+60).put("stop_timestamp",now+3600)).put(new JSONObject().put("id","now").put("title","TmV3cw==").put("description","SGVsbG8=").put("start_timestamp",now-60).put("stop_timestamp",now+60));List<Programme> parsed=Programme.parse(rows,TimeZone.getTimeZone("UTC"),false,0,now);assertEquals("News",parsed.get(0).title);assertEquals("Hello",parsed.get(0).description);assertEquals(0,Programme.current(parsed,now));assertFalse(parsed.get(0).archive);}
 @Test public void archiveRequiresAvailabilityAndPastCompleteWindow()throws Exception{long now=1700000000;JSONArray rows=new JSONArray().put(new JSONObject().put("id",1).put("title","Past show").put("start",now-7200).put("end",now-3600).put("has_archive",1));assertTrue(Programme.parse(rows,TimeZone.getTimeZone("UTC"),true,3,now).get(0).archive);rows.getJSONObject(0).put("has_archive",0);assertFalse(Programme.parse(rows,TimeZone.getTimeZone("UTC"),true,3,now).get(0).archive);rows.getJSONObject(0).put("has_archive",1).put("start",now-10).put("end",now+100);assertFalse(Programme.parse(rows,TimeZone.getTimeZone("UTC"),true,3,now).get(0).archive);}
 @Test public void macArchiveHonorsExplicitRecordingWithoutInventedWindow()throws Exception{long now=1700000000;JSONArray rows=new JSONArray().put(new JSONObject().put("id",4).put("name","Archived").put("start_timestamp",now-7200).put("stop_timestamp",now-3600).put("mark_archive",1));assertTrue(Programme.parse(rows,TimeZone.getTimeZone("UTC"),true,0,now).get(0).archive);rows.getJSONObject(0).put("mark_archive",0);assertFalse(Programme.parse(rows,TimeZone.getTimeZone("UTC"),true,0,now).get(0).archive);}
 @Test public void guideParsesMillisAndServerTimezone(){assertEquals(1700000000,Programme.timestamp("1700000000000",TimeZone.getTimeZone("UTC")));assertEquals(Programme.timestamp("2026-01-01 00:00:00",TimeZone.getTimeZone("UTC"))-14400,Programme.timestamp("2026-01-01 00:00:00",TimeZone.getTimeZone("Asia/Dubai")));assertEquals("Plain title",Programme.decode("Plain title"));}
 @Test public void historyDeduplicatesPerTypeAndCapsEntries()throws Exception{JSONArray history=new JSONArray();history=WatchHistory.remember(history,new JSONObject().put("kind","vod").put("uid","item:4").put("positionMs",10000),3);history=WatchHistory.remember(history,new JSONObject().put("kind","series").put("uid","item:4"),3);history=WatchHistory.remember(history,new JSONObject().put("kind","vod").put("uid","item:4").put("positionMs",60000),3);assertEquals(2,history.length());assertEquals(60000,WatchHistory.find(history,"vod","item:4").getLong("positionMs"));assertNotNull(WatchHistory.find(history,"series","item:4"));history=WatchHistory.remember(history,new JSONObject().put("kind","vod").put("uid","item:5"),2);assertEquals(2,history.length());assertNull(WatchHistory.find(history,"series","item:4"));}
 @Test public void resumeSkipsCompletedAndSupportsShortVideos(){assertFalse(WatchHistory.resumable(5000,100000));assertTrue(WatchHistory.resumable(30000,60000));assertFalse(WatchHistory.resumable(59000,60000));assertTrue(WatchHistory.resumable(1000000,5000000));assertFalse(WatchHistory.resumable(4990000,5000000));}
 @Test public void pinUsesRandomSaltAndRejectsWrongPin()throws Exception{String first=PinHash.create("1234"),second=PinHash.create("1234");assertNotEquals(first,second);assertTrue(PinHash.verify("1234",first));assertFalse(PinHash.verify("1235",first));try{PinHash.create("12");fail();}catch(IllegalArgumentException expected){}}
 @Test public void reconnectIsBoundedAndDoesNotRetryAuthorizationFailures(){assertEquals(2000,ReconnectPolicy.delay(0));assertEquals(4000,ReconnectPolicy.delay(1));assertEquals(8000,ReconnectPolicy.delay(2));assertEquals(-1,ReconnectPolicy.delay(3));assertTrue(ReconnectPolicy.transientHttp(503));assertFalse(ReconnectPolicy.transientHttp(403));assertFalse(ReconnectPolicy.transientHttp(511));assertFalse(ReconnectPolicy.transientHttp(488));}
 @Test public void diagnosticMessagesHideCredentialFieldsAndStreamUrls(){String value=DiagnosticText.redact("HTTP failure https://host.test/live/u/password/4.ts password=private123 token=secret456 username=someone");assertFalse(value.contains("private123"));assertFalse(value.contains("secret456"));assertFalse(value.contains("someone"));assertFalse(value.contains("https://"));assertTrue(value.contains("[redacted]"));}
}
